window.BOOK={"key":"ibnzurayq","app":"mutoon-ibnzurayq","lsk":"mutoon_ibnzurayq_v1","prefix":"ib_","title":"عينية ابن زريق","sub":"الشعر العربي · ابن زريق البغدادي (ت نحو ٤٢٠هـ) · ٤٠ بيتًا","poems":[{"id":"ibnzurayq","title":"عينية ابن زريق","nazim":"أبو الحسن علي بن زريق الكاتب البغدادي","death":"ت نحو ٤٢٠هـ","meter":"البسيط","source":"موقع الديوان (النص المشكول): «لا تعذليه فإن العذل يولعه»","srcUrl":"https://www.aldiwan.net/poem13279.html","note":"عينية ابن زريق البغدادي «لا تعذليه فإن العذل يولعه» كاملة (٤٠ بيتًا) بالرواية المتداولة، من نص موقع الديوان المشكول، قوبلت كلمةً كلمةً بسكربت بنص ويكي مصدر (٣٩ بيتًا) وبرواية السبكي المسندة في «طبقات الشافعية الكبرى» (٣٨ بيتًا، وفيها اختلافات كثيرة مثبتة في التقرير)، وأُبقي لفظ الأساس كله. أُكمل من الشكل ما يقتضيه اصطلاح المصدر (حركة ما قبل حرف المد وسكون أل وشدة الحرف الشمسي: ١٧٨ حركة)، وصُحّحت عشرة أخطاء ظاهرة في الحركات، وفُحص وزن كل شطر، والتفصيل في تقرير المصادر.","verses":[["لَا تَعْذُلِيهِ فَإِنَّ الْعَذْلَ يُولِعُهُ","قَدْ قُلْتِ حَقًّا وَلَكِنْ لَيْسَ يَسْمَعُهُ"],["جَاوَزْتِ فِي نُصْحِهِ حَدًّا أَضَرَّ بِهِ","مِنْ حَيْثُ قَدَّرْتِ أَنَّ النُّصْحَ يَنْفَعُهُ"],["فَاسْتَعْمِلِي الرِّفْقَ فِي تَأْنِيبِهِ بَدَلًا","مِنْ عَذْلِهِ فَهْوَ مُضْنَى الْقَلْبِ مُوجَعُهُ"],["قَدْ كَانَ مُضْطَلِعًا بِالْخَطْبِ يَحْمِلُهُ","فَضُيِّقَتْ بِخُطُوبِ الدَّهْرِ أَضْلُعُهُ"],["يَكْفِيهِ مِنْ لَوْعَةِ التَّشْتِيتِ أَنَّ لَهُ","مِنَ النَّوَى كُلَّ يَوْمٍ مَا يُرَوِّعُهُ"],["مَا آبَ مِنْ سَفَرٍ إِلَّا وَأَزْعَجَهُ","رَأْيٌ إِلَى سَفَرٍ بِالْعَزْمِ يُزْمِعُهُ"],["كَأَنَّمَا هُوَ فِي حِلٍّ وَمُرْتَحَلٍ","مُوَكَّلٌ بِفَضَاءِ اللَّهِ يَذْرَعُهُ"],["إِذَا الزَّمَانُ أَرَاهُ فِي الرَّحِيلِ غِنًى","وَلَوْ إِلَى السِّنْدِ أَضْحَى وَهْوَ يُزْمِعُهُ"],["تَأْبَى الْمَطَامِعُ إِلَّا أَنْ تُجَشِّمَهُ","لِلرِّزْقِ كَدًّا وَكَمْ مِمَّنْ يُوَدِّعُهُ"],["وَمَا مُجَاهَدَةُ الْإِنْسَانِ تُوصِلُهُ","رِزْقًا وَلَا دَعَةُ الْإِنْسَانِ تَقْطَعُهُ"],["قَدْ وَزَّعَ اللَّهُ بَيْنَ الْخَلْقِ رِزْقَهُمُ","لَمْ يَخْلُقِ اللَّهُ مِنْ خَلْقٍ يُضَيِّعُهُ"],["لَكِنَّهُمْ كُلِّفُوا حِرْصًا فَلَسْتَ تَرَى","مُسْتَرْزِقًا وَسِوَى الْغَايَاتِ تُقْنِعُهُ"],["وَالْحِرْصُ فِي الرِّزْقِ وَالْأَرْزَاقُ قَدْ قُسِمَتْ","بَغْيٌ أَلَا إِنَّ بَغْيَ الْمَرْءِ يَصْرَعُهُ"],["وَالدَّهْرُ يُعْطِي الْفَتَى مِنْ حَيْثُ يَمْنَعُهُ","إِرْثًا وَيَمْنَعُهُ مِنْ حَيْثُ يُطْمِعُهُ"],["أَسْتَوْدِعُ اللَّهَ فِي بَغْدَادَ لِي قَمَرًا","بِالْكَرْخِ مِنْ فَلَكِ الْأَزْرَارِ مَطْلَعُهُ"],["وَدَّعْتُهُ وَبِوُدِّي لَوْ يُوَدِّعُنِي","صَفْوُ الْحَيَاةِ وَأَنِّي لَا أُوَدِّعُهُ"],["وَكَمْ تَشَفَّعَ بِي أَنْ لَا أُفَارِقَهُ","وَلِلضَّرُورَاتِ حَالٌ لَا تُشَفِّعُهُ"],["وَكَمْ تَشَبَّثَ بِي يَوْمَ الرَّحِيلِ ضُحًى","وَأَدْمُعِي مُسْتَهِلَّاتٌ وَأَدْمُعُهُ"],["لَا أَكْذِبُ اللَّهَ ثَوْبُ الصَّبْرِ مُنْخَرِقٌ","عَنِّي بِفُرْقَتِهِ لَكِنْ أُرَقِّعُهُ"],["إِنِّي أُوَسِّعُ عُذْرِي فِي جِنَايَتِهِ","بِالْبَيْنِ عَنْهُ وَجُرْمِي لَا يُوَسِّعُهُ"],["رُزِقْتُ مُلْكًا فَلَمْ أُحْسِنْ سِيَاسَتَهُ","وَكُلُّ مَنْ لَا يَسُوسُ الْمُلْكَ يُخْلَعُهُ"],["وَمَنْ غَدَا لَابِسًا ثَوْبَ النَّعِيمِ بِلَا","شُكْرٍ عَلَيْهِ فَإِنَّ اللَّهَ يَنْزَعُهُ"],["اعْتَضْتُ مِنْ وَجْهِ خِلِّي بَعْدَ فُرْقَتِهِ","كَأْسًا يُجَرَّعُ مِنْهَا مَا أُجَرَّعُهُ"],["كَمْ قَائِلٍ لِيَ ذُقْتَ الْبَيْنَ قُلْتُ لَهُ","الذَّنْبُ وَاللَّهِ ذَنْبِي لَسْتُ أَدْفَعُهُ"],["أَلَا أَقَمْتُ فَكَانَ الرُّشْدُ أَجْمَعُهُ","لَوْ أَنَّنِي يَوْمَ بَانَ الرُّشْدُ أَتْبَعُهُ"],["إِنِّي لَأَقْطَعُ أَيَّامِي وَأُنْفِقُهَا","بِحَسْرَةٍ مِنْهُ فِي قَلْبِي تُقَطِّعُهُ"],["بِمَنْ إِذَا هَجَعَ النُّوَّامُ بِتُّ لَهُ","بِلَوْعَةٍ مِنْهُ لَيْلِي لَسْتُ أَهْجَعُهُ"],["لَا يَطْمَئِنُّ لِجَنْبِي مَضْجَعٌ وَكَذَا","لَا يَطْمَئِنُّ لَهُ مُذْ بِنْتُ مَضْجَعُهُ"],["مَا كُنْتُ أَحْسَبُ أَنَّ الدَّهْرَ يَفْجَعُنِي","بِهِ وَلَا أَنَّ بِي الْأَيَّامَ تَفْجَعُهُ"],["حَتَّى جَرَى الْبَيْنُ فِيمَا بَيْنَنَا بِيَدٍ","عَسْرَاءَ تَمْنَعُنِي حَظِّي وَتَمْنَعُهُ"],["قَدْ كُنْتُ مِنْ رَيْبِ دَهْرِي جَازِعًا فَرِقًا","فَلَمْ أُوَقَّ الَّذِي قَدْ كُنْتُ أَجْزَعُهُ"],["بِاللَّهِ يَا مَنْزِلَ الْعَيْشِ الَّذِي دَرَسَتْ","آثَارُهُ وَعَفَتْ مُذْ بِنْتُ أَرْبُعُهُ"],["هَلِ الزَّمَانُ مُعِيدٌ فِيكَ لَذَّتَنَا","أَمِ اللَّيَالِي الَّتِي أَمْضَتْهُ تُرْجِعُهُ"],["فِي ذِمَّةِ اللَّهِ مَنْ أَصْبَحْتَ مَنْزِلَهُ","وَجَادَ غَيْثٌ عَلَى مَغْنَاكَ يُمْرِعُهُ"],["مَنْ عِنْدَهُ لِيَ عَهْدٌ لَا يُضَيِّعُهُ","كَمَا لَهُ عَهْدُ صِدْقٍ لَا أُضَيِّعُهُ"],["وَمَنْ يُصَدِّعُ قَلْبِي ذِكْرُهُ وَإِذَا","جَرَى عَلَى قَلْبِهِ ذِكْرِي يُصَدِّعُهُ"],["لَأَصْبِرَنَّ لِدَهْرٍ لَا يُمَتِّعُنِي","بِهِ وَلَا بِيَ فِي حَالٍ يُمَتِّعُهُ"],["عِلْمًا بِأَنَّ اصْطِبَارِي مُعْقِبٌ فَرَجًا","فَأَضْيَقُ الْأَمْرِ إِنْ فَكَّرْتَ أَوْسَعُهُ"],["عَسَى اللَّيَالِي الَّتِي أَضْنَتْ بِفُرْقَتِنَا","جِسْمِي سَتَجْمَعُنِي يَوْمًا وَتَجْمَعُهُ"],["وَإِنْ تَنَلْ أَحَدًا مِنَّا مَنِيَّتُهُ","فَمَا الَّذِي بِقَضَاءِ اللَّهِ يَصْنَعُهُ"]],"secs":{"1":"عينية ابن زريق"}}],"sharh":false};
